static ano_crypto_status_t ecdsa_import_private(ano_crypto_csp_handle_t *out)
{
    return ano_crypto_ec_p256_key_import(
        ECDSA_P256_X, sizeof(ECDSA_P256_X), ECDSA_P256_Y, sizeof(ECDSA_P256_Y),
        ECDSA_P256_D, sizeof(ECDSA_P256_D), ANO_CRYPTO_KEY_FLAG_NONE, out);
}
static ano_crypto_status_t ecdsa_import_public(ano_crypto_csp_handle_t *out)
{
    return ano_crypto_ec_p256_key_import(
        ECDSA_P256_X, sizeof(ECDSA_P256_X), ECDSA_P256_Y, sizeof(ECDSA_P256_Y),
        NULL, 0u, ANO_CRYPTO_KEY_FLAG_NONE, out);
}

